WebBarcodes.wbOnScan:
console.log("(Barcode Open Employee)", this.parameters);

m1.backTo({
	screen: 'employee',
	parameters: { employee: this.parameters.employee },
	parent: {
		list: 'employees',
		filters: {
			lmeDefaultWorkCenterID: m1.options.filterEmpByWc,
			lmeHomeProductionDepartmentID: m1.options.filterEmpByDept
		}
	}
});

console.log("(Barcode Issue Lot Number)", this.parameters);

lotNumber = this.parameters.lotNumber

m1.backTo({
	screen: 'part', 
	parameters: {
		part: this.parameters.part, 
		revision: this.parameters.revision, 
		employee: m1.employee
	},
	onReady: function() {
		this.lotNumber.setValue(lotNumber, true);
	},
	parent: {
		list: 'groupedJobMaterials',
		parameters: {
			employee: m1.employee,
			filterByAssembly: m1.options.filterMaterialByAssembly,
			filterByOperation: m1.options.filterMaterialByOperation
		}
	}	
});

console.log("(Barcode Job Material)", this.parameters);

m1.backTo({
	screen: "jobMaterial",
	parameters: {
		job: this.parameters.job,
		assembly: this.parameters.assembly,
		material: this.parameters.material
	},
	parent: {
		list: "jobMaterials",
		filters: {
			jmmJobID: this.parameters.job
		}
		parent: {
			screen: "job",
			parameters {
				job: this.parameters.job
			}
			parent: {
				parent: { list: "jobs" }
			}
		}
	}
});

console.log("(Barcode Job Material)", this.parameters);

m1.backTo({
	screen:'jobMaterial', 
	parameters: {
		job: this.parameters.job,
		assembly: this.parameters.assembly,
		material: this.parameters.material
	},
	parent: {
		screen: 'employee',
		parameters: { employee: m1.employee },
		parent: {
			list: 'employees',
			filters: {
				lmeDefaultWorkCenterID: m1.options.filterEmpByWc,
				lmeHomeProductionDepartmentID: m1.options.filterEmpByDept
			}
		}
	}
});

console.log("(Barcode Open Job Operation)", this.parameters);

m1.backTo({
	screen: "jobOperation",
	parameters: {
		job: this.parameters.job, 
		assembly: this.parameters.assembly, 
		operation: this.parameters.operation, 
		employee: m1.employee
	},
	parent: {
		screen: 'employee',
		parameters: { employee: m1.employee },
		parent: {
			list: 'employees',
			filters: {
				lmeDefaultWorkCenterID: m1.options.filterEmpByWc,
				lmeHomeProductionDepartmentID: m1.options.filterEmpByDept
			}
		}
	}
}

console.log("(Barcode Issue Part)", this.parameters);

m1.backTo({
	screen: "part",
	parameters: {
		part: this.parameters.part, 
		revision: this.parameters.revision, 
		employee: m1.employee
	},
	parent: {
		list: "groupedJobMaterials",
		parameters: {
			employee: m1.employee,
			filterByAssembly: m1.options.filterMaterialByAssembly,
			filterByOperation: m1.options.filterMaterialByOperation
		}
	}
});

console.log("(Barcode Issue Serial Number)", this.parameters);

serialNumber = this.parameters.serialNumber;

m1.backTo({
	screen: "part",
	parameters: {
		part: this.parameters.part, 
		revision: this.parameters.revision, 
		employee: m1.employee
	},
	onReady: function() {
		this.serialNumber.setValue(serialNumber, true);
	},
	parent: {
		list: 'groupedJobMaterials',
		parameters: {
			employee: m1.employee,
			filterByAssembly: m1.options.filterMaterialByAssembly,
			filterByOperation: m1.options.filterMaterialByOperation
		}
	}
});
